import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes0')
from h import *
X=[]
X.append(r(9000851,"Relleno vegano en olla (estilo estufa)","Este FÁCIL relleno vegano en olla está listo en solo 30 minutos. ¡Perfecto para Acción de Gracias, Navidad o cualquier día!","8 porciones","1 porción",
["300 gramos de pan integral en rebanadas, cortado en cubos de 1\" (aprox. 6 tazas de cubos)","1 taza de nueces pecanas o nueces de Castilla picadas","2 cucharadas de mantequilla vegana (omítala y use caldo para saltear si desea una versión sin aceite)","1 cebolla amarilla picada en cubos","2 zanahorias peladas + picadas en cubos","2 tallos de apio picados en cubos","3-4 dientes de ajo pelados + picados finamente","1.5 cucharaditas de salvia seca","1 cucharadita de tomillo seco","1 cucharadita de romero seco triturado","2-3 tazas de caldo de verduras bajo en sodio (comience con 2 tazas y agregue más si es necesario)","sal + pimienta al gusto",("Guarnición opcional","romero fresco")],
["Precaliente el horno a 400 grados F y cubra una bandeja para hornear con papel pergamino.","Coloque los cubos de pan y las nueces pecanas picadas en la bandeja y hornee durante 8 minutos, o hasta que estén bien tostados. Retire del horno y reserve.","Mientras tanto, derrita la mantequilla (si la usa) en una sartén grande y agregue todas las verduras picadas y los condimentos. Saltee durante 7-8 minutos, hasta que las verduras estén suaves y doradas.","Agregue el pan tostado y las nueces pecanas a la sartén con las verduras y vierta 2 tazas de caldo encima. Mezcle bien. Pruebe y ajuste la sal y la pimienta, y agregue más caldo si prefiere un relleno más suave. Sirva y disfrute."],
["Yo usé media barra de este pan Dempster’s Ancient Grains con quinoa. Puede usar cualquier pan en rebanadas que le guste, o pan casero. Al principio, comience con solo 2 tazas de caldo. Mezcle bien y agregue más si prefiere un relleno más suave."],[]))
X.append(r(9005196,"Pan integral de higos y nueces - ¡sin amasar!","Un delicioso pan de higos y nueces, hecho con harina integral y sin necesidad de amasar.","12 rebanadas","1 porción",
["520 gramos de harina integral (aprox. 4 tazas)","1 sobre de 8 gramos de levadura instantánea (aprox. 2 ¼ cucharaditas)","¾ de cucharadita de sal marina","1 cucharada de jarabe de arce u otro endulzante como jarabe de dátil o de agave","2 tazas de agua tibia","½ taza de higos secos bien compactados (aprox. 6-7 higos, picados en trozos pequeños)","½ taza de trozos de nueces de Castilla bien compactados"],
["Cubra un molde para pan de 5 x 9 pulgadas con papel pergamino y resérvelo.","Ponga la harina, la levadura instantánea y la sal en un tazón grande y mezcle bien.","Luego agregue el jarabe de arce a un tazón de agua tibia y mezcle para disolver. Después vierta el agua en el tazón con la harina y mezcle con una espátula de silicona, sin mezclar en exceso, y NO AMASE.","Incorpore con movimientos envolventes los higos picados y los trozos de nueces, y luego pase la masa al molde preparado. Cubra el molde con envoltura de plástico y déjelo reposar durante 20 minutos. La masa casi duplicará su tamaño y el pan llegará hasta la parte superior del molde. (Vea las notas)","Mientras tanto, precaliente el horno a 400°F/204°C y luego hornee el pan de higos y nueces ya crecido durante 40 minutos. Retire del horno y deje enfriar antes de rebanar."],
["Pese la harina para obtener mejores resultados. El volumen de la harina varía según el método de medición, por ejemplo, tomarla con la taza y nivelarla, o ponerla con una cuchara dentro de la taza medidora. Use una báscula de cocina para medir la harina con mayor exactitud. Asegúrese de usar agua tibia para mezclar con el jarabe de arce, y NO fría. Necesita agua tibia para activar la levadura. NO AMASE la masa. Mezcle hasta que no queden restos de harina, sin mezclar en exceso. Cuando el pan llegue a la parte superior del molde, estará listo para hornear. No deje que el pan crezca por encima de los bordes del molde, o terminará con una parte superior desbordada como la de un muffin. Esto normalmente tarda 20 minutos, pero si todavía no ha llegado, déjelo 5 minutos más. El pan recién horneado sabe mejor el mismo día en que se prepara, pero puede guardarlo a temperatura ambiente durante 3-4 días. Para congelarlo, asegúrese de que el pan esté completamente frío, a temperatura ambiente. Luego envuélvalo bien con envoltura de plástico y colóquelo en un recipiente hermético apto para congelador. Debe mantener el aire alejado del pan en el congelador para evitar que se queme por congelación."],[]))
X.append(r(9005368,"Hamburguesas veganas de “pollo” [sin gluten + sin aceite]","Sazonadas con sabores de ave y horneadas hasta quedar doradas y crujientes. ¡Estas hamburguesas veganas de “pollo” son sabrosas, nutritivas y deliciosas!","8 hamburguesas","1 g",
["1 taza de arroz integral cocido, apenas compactado","3 tazas de papa amarilla pelada y cortada en cubos","1 lata de 15 onzas de garbanzos, escurridos y enjuagados, o 1.5 tazas cocidos","1 taza de avena cortada de cocción rápida o avena en hojuelas","2 cucharadas de agua","2 cucharadas de levadura nutricional","1 cucharadita de ajo en polvo","1 cucharadita de cebolla en polvo","¾ de cucharadita de sal marina","¼ de cucharadita de orégano seco","¼ de cucharadita de tomillo seco","¼ de cucharadita de salvia seca","¼ de cucharadita de romero seco triturado"],
["Precaliente el horno a 425 grados F y cubra una bandeja para hornear con papel pergamino.","Cubra los cubos de papa con agua con sal en una olla pequeña y hierva. Cocine durante 10 minutos, o hasta que se pinchen fácilmente con un tenedor. Escurra y colóquelas en un tazón grande. Luego macháquelas suavemente con un machacador de papas hasta que se deshagan, sin triturarlas en exceso. Debe conservar algo de textura. Reserve.","Ponga el arroz, los garbanzos, la avena, el agua y todos los condimentos en el procesador de alimentos. Pulse hasta que todo esté integrado y desmenuzado, sin procesar en exceso. No debe hacer un puré con la mezcla.","Pase los ingredientes procesados al tazón con el puré de papa y mezcle bien con una espátula.","Con las manos húmedas, apriete la mezcla para formar una bola y luego presione para darle forma de disco. Mantenga las hamburguesas más bien delgadas y colóquelas en la bandeja preparada. Repita con el resto de la mezcla. Debe obtener 8 hamburguesas grandes.","Hornee durante 20 minutos, luego voltee con cuidado y hornee otros 10 minutos, o hasta que estén ligeramente doradas.","Sirva las hamburguesas veganas de “pollo” con pan o sin él, y con todos sus aderezos favoritos."],
["Para dar más profundidad de sabor, cocine las papas (y el arroz, si no tiene sobras) en caldo o con un poco de caldo en polvo. No triture demasiado las papas. Recuerde que no está haciendo puré de papa; deben quedar con grumos para lograr hamburguesas con mejor textura. Solo macháquelas unas cuantas veces para asegurarse de que no queden trozos demasiado grandes. No procese en exceso la mezcla de arroz y garbanzos. De nuevo, para lograr las mejores hamburguesas veganas de “pollo” en cuanto a textura, debe conservar algo de consistencia y no hacer un puré con los ingredientes. Use las manos húmedas para dar forma a las hamburguesas. Mantenga un tazón pequeño con agua cerca, o trabaje cerca del fregadero y moje ligeramente las manos antes de formar cada bola y de nuevo antes de aplanar cada hamburguesa. Esto le ayudará a darles forma sin que la mezcla se pegue a las manos. También ayudará a evitar que se agrieten mientras les da forma. Mantenga las hamburguesas veganas de “pollo” más bien delgadas para lograr la mejor textura y que queden crujientes. ¿Va a servir a los pequeños? Haga algunas hamburguesas más pequeñas para servirlas como nuggets veganos de “pollo”. Refrigere las sobras durante 3-4 días o congélelas hasta por 3 meses. Para congelar, cocine según las indicaciones y congele en un recipiente hermético. Separe cada hamburguesa con papel pergamino para evitar que se peguen y recaliente en el horno. La información nutricional corresponde a 1 hamburguesa vegana de “pollo”. El pan y los aderezos no están incluidos en el cálculo."],[]))
X.append(r(9007563,"Pimientos rellenos veganos al estilo mexicano con salsa de queso de nuez","¡Pimientos rellenos veganos al estilo mexicano, que hacen agua la boca y son increíblemente sabrosos!","4 porciones","1 porción",
["4 pimientos morrones grandes de cualquier color, cortados por la mitad a lo largo y sin semillas","1 taza de quinoa enjuagada y escurrida","2 tazas de caldo de verduras bajo en sodio","1.5 tazas de frijoles negros cocidos o de lata","1 taza de maíz congelado, descongelado","½ taza de salsa mediana con trozos o su salsa favorita","1.5 cucharaditas de pimentón ahumado","1.5 cucharaditas de chile en polvo","1 cucharadita de comino","sal + pimienta al gusto",("Aderezos opcionales","salsa de queso de nuez (muy recomendada)"),("Aderezos opcionales","aguacate en rebanadas, tomate picado en cubos, jalapeño"),("Aderezos opcionales","pico de gallo con piña"),("Aderezos opcionales","guacamole"),("Aderezos opcionales","cilantro picado")],
["Ponga la quinoa y el caldo en una olla mediana y hierva. Luego reduzca el fuego y cocine a fuego lento hasta que se absorba el líquido, aprox. 15 minutos. Revuelva con frecuencia hacia el final de la cocción para evitar que se pegue. Retire del fuego y agregue los frijoles negros, el maíz, la salsa y todos los condimentos a la quinoa cocida. Mezcle bien y luego pruebe y ajuste los condimentos al gusto.","Mientras tanto, precaliente el horno a 425°F/218°C y cubra un molde para hornear de 9\"x13\" con papel pergamino. Coloque las mitades de pimiento con el lado cortado hacia arriba en el molde y espolvoréelas con sal y pimienta.","Divida la mezcla entre las 8 mitades de pimiento, luego cubra el molde con papel pergamino y después con papel de aluminio. Hornee durante 30-35 minutos, hasta que los pimientos estén tiernos.","Mientras se hornean los pimientos, prepare los aderezos opcionales. Luego sirva."],
["Para obtener mejores resultados, cocine la quinoa (o el arroz) en un caldo de verduras salado y sabroso. Puede usar agua con sal para cocinar la quinoa (en lugar de caldo), pero no tendrá tanto sabor. Si no le gusta la quinoa, use arroz y siga las mismas instrucciones de cocción, o use una arrocera. La información nutricional corresponde a un pimiento (o dos mitades de pimiento) y una cuarta parte del relleno preparado. No incluye los aderezos opcionales."],[]))
X.append(r(9014896,"Bisque vegano de tomate [¡con tomates frescos!]","Un bisque vegano de tomate, espeso y cremoso, hecho en una sola olla y lleno de sabor a tomate fresco. Es sedoso y reconfortante, ¡pero no se siente pesado!","6 porciones","1 porción",
["1 cucharada de mantequilla vegana (opcional; omítala para una versión sin aceite y saltee con agua o caldo)","1 cebolla amarilla grande, picada en trozos grandes","1 tallo de apio picado en trozos grandes","4 dientes de ajo pelados y picados en trozos grandes","½ cucharadita de pimentón ahumado","½ cucharadita de sal marina","¼ de taza de harina integral (o harina sin gluten, si lo prefiere)","3 libras de tomates de campo o madurados en la rama, cortados en cuartos","3 tazas de caldo de verduras bajo en sodio","2 hojas de laurel","2 ramitas de perejil fresco","454 gramos de tofu mediano/firme (de preferencia no transgénico, o de tamaño similar)","sal + pimienta al gusto"],
["Derrita la mantequilla, si la usa, en una olla grande y agregue la cebolla, el apio y el ajo picados. Saltee, revolviendo con frecuencia, hasta que se ablanden y la cebolla esté translúcida, unos 5 minutos.","Agregue el pimentón ahumado y la sal y mezcle bien. Baje el fuego y añada un chorrito de agua y la harina, y revuelva constantemente durante unos 30 segundos.","Ahora agregue los tomates picados a la olla y cocínelos, revolviendo con frecuencia, durante 1-2 minutos. Luego vierta el caldo, las hojas de laurel y el perejil. Mezcle bien y hierva a fuego medio, cocinando durante unos 20-25 minutos, revolviendo de vez en cuando.","Retire del fuego y retire y deseche las hojas de laurel. Agregue el tofu y, con una batidora de inmersión, haga un puré con la sopa de tomate. Cuando esté suave, pruebe y ajuste la sal y la pimienta, si es necesario.","Sirva decorado con albahaca fresca y disfrute."],
["Para obtener mejores resultados, deje reposar la olla de sopa ya cocida y hecha puré durante 10 minutos antes de servir. Este breve reposo espesará un poco más la sopa. Si no tiene una batidora de inmersión, puede pasar la sopa con cuidado, por tandas, a una licuadora de vaso. Tenga mucha precaución al licuar líquidos calientes, no llene la licuadora hasta arriba y trabaje en tantas tandas como sea necesario. Para una versión sin aceite, omita la mantequilla y saltee con agua o caldo. Agregue más según sea necesario para evitar que se pegue. Para una versión sin soya, omita el tofu y use 1.5 tazas de crema de anacardos (nueces de la India) para incorporar al final. Tenga en cuenta que esto aumentará el contenido de grasa. O bien, use una lata de 15 oz de frijoles cannellini blancos escurridos y enjuagados si desea evitar tanto la soya como las nueces. Los bloques de tofu varían de tamaño; esta vez uso un bloque de 454 g de tofu mediano/firme, pero cualquier tamaño entre 350 y 454 g funcionará bien para esta receta. Las sobras se conservan en el refrigerador hasta por 3 días, o puede congelarlas por 2-3 meses."],[]))
X.append(r(9021259,"Carbonara vegana fácil con “panceta” de soya texturizada","Espagueti tierno con “panceta” ahumada de soya texturizada y una deliciosa salsa con sabor a huevo hacen de esta carbonara vegana algo inolvidable.","6 porciones","1 porción",
[("Para la “panceta” vegana","4 onzas de soya texturizada en tiras (soy curls), aprox. media bolsa de Butler's"),("Para la “panceta” vegana","⅓ de taza de salsa de soya baja en sodio o tamari para una versión sin gluten"),("Para la “panceta” vegana","2 cucharadas de jarabe de arce"),("Para la “panceta” vegana","2 cucharaditas de pimentón ahumado"),("Para la “panceta” vegana","½ cucharaditas de pimienta negra"),("Para la salsa vegana con sabor a huevo","300 gramos de tofu suave"),("Para la salsa vegana con sabor a huevo","¼ de taza de levadura nutricional"),("Para la salsa vegana con sabor a huevo","3 cucharadas de vinagre de manzana"),("Para la salsa vegana con sabor a huevo","1 cucharadita de cúrcuma"),("Para la salsa vegana con sabor a huevo","1 cucharadita de cebolla en polvo"),("Para la salsa vegana con sabor a huevo","1 cucharadita de sal negra, también conocida como Kala Namak"),("Para la salsa vegana con sabor a huevo","⅓ de taza de leche de soya sin azúcar o la leche vegetal que prefiera"),("Para la pasta","410 gramos (14.5 oz) de espagueti o espaguetini, sin gluten si lo prefiere"),("Guarniciones opcionales","queso parmesano vegano"),("Guarniciones opcionales","pimienta negra, perejil fresco, albahaca fresca y/o hojuelas de chile rojo")],
["Desmenuce con las manos la soya texturizada en trozos pequeños y colóquelos en un tazón mediano. (No es necesario que tengan el mismo tamaño).","En un tazón pequeño, mezcle el adobo de la “panceta”: tamari, jarabe de arce, pimentón ahumado y pimienta negra. Vierta la mezcla sobre los trozos de soya texturizada, revuelva hasta que queden cubiertos de manera uniforme y reserve durante 5 minutos. Luego revuelva de nuevo para que absorban todo el adobo.","Hierva una olla grande con agua con sal y cocine la pasta según las indicaciones del paquete para una pasta “al dente”.","Mientras tanto, caliente una sartén honda a fuego y, cuando esté caliente, agregue la soya texturizada. Saltee en seco durante unos 5 minutos, revolviendo con frecuencia, hasta que esté dorada, sin quemarla. Luego apague el fuego y reserve. (Si desea decorar los platos con la soya texturizada más adelante, aparte un puñado de trozos).","Ponga todos los ingredientes de la salsa en la licuadora y procese hasta que quede suave. Reserve.","Cuando la pasta esté cocida, RESERVE 1 taza del agua de cocción antes de escurrirla. Agregue el espagueti cocido a la sartén y vierta encima la salsa carbonara. Luego ponga la taza de agua de la pasta en la licuadora vacía, muévala bien o licúe de nuevo unos segundos para recoger la salsa y los condimentos que quedaron en las paredes. Vierta esto en la sartén y mezcle bien.","Sirva con pimienta negra, hierbas frescas y/o queso parmesano vegano."],
["¡Ponga sal al agua de la pasta! Asegúrese de agregar suficiente sal al agua de la olla para obtener mejores resultados. Aquí hay una guía práctica por si la necesita. No cocine demasiado la pasta. Siga las indicaciones para pasta “al dente”. Si su paquete no incluye indicaciones para “al dente”, cocine la pasta de 1 a 3 minutos menos. “Al dente” significa que la pasta todavía está firme una vez cocida, y no blanda. Esto le da la textura ideal. Reserve algo del agua de la pasta para “enjuagar” la licuadora al escurrir los fideos. Si lo olvida, use un poco de caldo, o agua fresca con un poco de sal, para no diluir demasiado la salsa carbonara, aunque el agua con almidón funciona mejor. La sal negra, también llamada Kala Namak, es un ingrediente fundamental en este platillo. Es lo que le da a la salsa su sabor a huevo. No la omita si es posible. Si no la tiene o no la encuentra, puede usar sal marina, con resultados un poco diferentes. Sirva la carbonara vegana de inmediato, ya que la pasta absorberá la salsa a medida que se enfríe. Las sobras se conservan en el refrigerador durante 3-4 días. Agregue un poco de caldo o leche vegetal a la sartén al recalentar para aflojarla y devolverle humedad. La “panceta” de soya texturizada está inspirada en los trocitos de tocino vegano de My Quiet Kitchen."],[]))
X.append(r(9021515,"Fiambre vegano en rebanadas [rebanadas de “pavo” de seitán]","Estas sustanciosas rebanadas veganas tipo fiambre, de aspecto “carnoso”, quedan jugosas, llenas de sabor y son fáciles de preparar.","8 porciones","1 porción",
["130 gramos de gluten de trigo vital (aprox. 1 taza colmada)","350 gramos (12 onzas) de un bloque de tofu extra firme, cortado en cubos","6 cucharadas de levadura nutricional","2 cucharadas de salsa de soya","1 cucharada de humo líquido","3 cucharaditas de condimento para ave","2 cucharaditas de ajo en polvo","2 cucharaditas de cebolla en polvo","1 cucharadita de vinagre de manzana","½ cucharadita de sal marina (opcional, pero como el fiambre tradicional es salado, la sal adicional ayuda a imitar ese sabor)"],
["Ponga todos los ingredientes en el procesador de alimentos y pulse hasta que se integren. Quedará desmenuzado, pero puede presionar todo con las manos, así que no se preocupe si no forma una bola perfecta.","Retire la mezcla del procesador y forme un rollo o un disco. Luego envuélvalo bien en una manta de cocina (gasa) y asegure los dos extremos como el envoltorio de un caramelo. (Vea las imágenes del proceso arriba como referencia).","Use una vaporera para colocar el seitán de “pavo” o improvise una si no tiene. Para ello, coloque un tazón resistente al calor sobre una olla con agua, asegurándose de que el tazón no toque el agua. Mantenga un hervor suave y tape el seitán con una tapa.","Cocine al vapor durante 45 minutos, luego voltéelo y cocine al vapor otros 35-45 minutos, o hasta que la temperatura interna alcance 160℉/71℃. Vigile el nivel del agua para que no se evapore por completo y agregue agua CALIENTE/hirviendo según sea necesario.","Para obtener mejores resultados y rebanar con facilidad, deje reposar el rollo de seitán de “pavo” a temperatura ambiente durante 30 minutos y luego refrigérelo toda la noche o varias horas, hasta que esté frío."],
["Use una báscula de cocina para pesar el gluten de trigo vital y lograr resultados más exactos y la mejor textura.","Vigile el nivel del agua durante la cocción al vapor para asegurarse de que no se acabe. Agregue más agua hirviendo a la olla según sea necesario para mantener un hervor suave.","El tiempo de cocción al vapor variará según la forma del rollo o disco de seitán de “pavo”, por lo que revisar la temperatura interna es la manera más fácil de obtener los mejores resultados.","Si no tiene manta de cocina (gasa), puede envolver el seitán en papel de aluminio. Sin embargo, para evitar que el aluminio toque los alimentos, puede usar primero papel pergamino y luego envolverlo en papel de aluminio.","Las sobras se conservan en el refrigerador hasta por 5 días en un recipiente cerrado. O congele el fiambre vegano en rebanadas o como rollo entero para usarlo más adelante."],[]))
X.append(r(9023396,"Crema vegana de champiñones [sin aceite]","La crema vegana de champiñones (o sopa vegana de champiñones) está llena de delicioso sabor umami. ¡Solo 7 ingredientes y 25 minutos de principio a fin!","3 porciones","1 porción",
["1 libra de champiñones cremini o baby bella, picados en trozos grandes","3 dientes de ajo pelados y picados finamente","¼ de cucharadita de tomillo seco","3 tazas de caldo de verduras bajo en sodio","1 cucharada de pasta de miso blanco","3 cucharadas de jugo de limón (aprox. 1 limón mediano)","1 taza de leche de soya sin azúcar o la leche vegetal que prefiera","sal + pimienta al gusto"],
["En una olla mediana o sartén honda, ponga los champiñones, el ajo, el tomillo y un par de gotas de agua para evitar que se peguen. Saltee hasta que los champiñones se reduzcan, aprox. 4 minutos.","Agregue el caldo, la pasta de miso y el jugo de limón y hierva a fuego bajo, cocinando durante unos 5 minutos. Apague el fuego, agregue la leche y luego use una batidora de inmersión para hacer un puré con la sopa O páselo a una licuadora. Pruebe y agregue sal y pimienta, solo si es necesario, y sirva con pan crujiente."],
["No ponga sal a la sopa antes de probarla, una vez hecha puré. La pasta de miso y el caldo de verduras aportan bastante sal. Una vez licuada, pruebe la sopa y agregue un poco, solo si es necesario. Use caldo de verduras bajo en sodio, o use una mezcla de caldo regular y agua si no tiene caldo bajo en sodio. Siempre puede agregar más sal si hace falta, pero no puede quitarla. Si no tiene una batidora de inmersión, pase la sopa con cuidado a una licuadora y procese hasta que quede suave. Tenga mucha precaución al licuar líquidos calientes, no llene demasiado la licuadora y trabaje por tandas, según sea necesario. Las sobras se conservan en el refrigerador hasta por 4 días o puede congelarlas hasta por 3 meses."],[]))
X.append(r(9028983,"Cupcakes veganos saludables de zanahoria","Cupcakes veganos de zanahoria húmedos, dulces y deliciosos, hechos con ingredientes nutritivos para disfrutar un gusto fantástico SIN culpa.","12 cupcakes","1 porción",
[("Para los cupcakes veganos de zanahoria","½ taza de leche de soya"),("Para los cupcakes veganos de zanahoria","¼ de taza de jugo de limón (aprox. 1 limón grande)"),("Para los cupcakes veganos de zanahoria","½ taza de compota de manzana sin azúcar"),("Para los cupcakes veganos de zanahoria","½ taza de jarabe de arce"),("Para los cupcakes veganos de zanahoria","1 taza compacta de zanahorias ralladas (aprox. 2 zanahorias grandes)"),("Para los cupcakes veganos de zanahoria","2 cucharaditas de extracto puro de vainilla"),("Ingredientes secos","240 gramos de harina integral para repostería (aprox. 2 tazas)"),("Ingredientes secos","1 cucharadita de canela molida"),("Ingredientes secos","¼ de cucharadita de nuez moscada molida"),("Ingredientes secos","2 cucharaditas de polvo para hornear"),("Ingredientes secos","½ cucharadita de bicarbonato de sodio"),("Opcional (elija 1 o ninguno)","½ taza de pasas"),("Opcional (elija 1 o ninguno)","½ taza de nueces de Castilla o nueces pecanas picadas"),("Para el glaseado vegano tipo queso crema","340 gramos de tofu extra firme, escurrido y secado con toallas de papel (use no transgénico si es posible)"),("Para el glaseado vegano tipo queso crema","¼ de taza de anacardos (nueces de la India) crudos"),("Para el glaseado vegano tipo queso crema","5-8 cucharadas de jarabe de arce"),("Para el glaseado vegano tipo queso crema","2-3 cucharaditas de jugo de limón")],
[("Para los cupcakes","Ponga la leche de soya y el jugo de limón en un tazón grande y déjelos reposar durante 5 minutos para que espesen y se cuajen. (Este es su suero de leche vegano)."),("Para los cupcakes","Precaliente el horno a 350°F/176°C y prepare un molde antiadherente para muffins. (O engrase el molde o los capacillos si es necesario)."),("Para los cupcakes","Una vez cuajado, agregue los demás ingredientes húmedos al tazón y mezcle bien. Luego agregue los ingredientes secos al mismo tazón y revuelva hasta que se integren SIN mezclar en exceso. (Si usa un ingrediente opcional, incorpórelo también con movimientos envolventes)."),("Para los cupcakes","Divida la masa de los cupcakes entre los 12 moldes del molde para muffins y hornee hasta que un palillo insertado en el centro de un cupcake salga limpio, aprox. 18 minutos. Retire del horno y deje reposar durante 10 minutos antes de pasarlos a una rejilla para enfriar."),("Para el glaseado","Ponga todos los ingredientes del glaseado en la licuadora y procese hasta que quede suave. Comience con 5 cucharadas del jarabe de arce, luego pruebe y agregue más hasta lograr el dulzor deseado. No se pase o el glaseado quedará demasiado blando."),("Para el glaseado","Cuando los cupcakes estén completamente fríos, cubra los cupcakes con el glaseado usando una manga pastelera y disfrute.")],
["Pese la harina para obtener resultados más exactos. Le recomiendo mucho que no se base en las medidas en tazas al hornear. Si no tiene una báscula de cocina, puede poner la harina con una cuchara en la taza medidora y usar un cuchillo para quitar el exceso, con resultados similares. ¡No la tome directamente de la bolsa!","Use un rallador de caja o un procesador de alimentos para rallar las zanahorias; de cualquier manera, lo mejor es rallarlas al momento, ya que las zanahorias ralladas que se compran pueden estar secas.","No mezcle en exceso la masa de los cupcakes. Revuelva hasta que no queden restos de harina, pero no se preocupe por deshacer todos los grumos. Mezclar en exceso puede dar una textura gomosa o densa.","Use polvo para hornear fresco y activo. El polvo para hornear que lleva abierto en la despensa 6 meses o más puede empezar a perder su efectividad.","Como estos cupcakes no llevan grasa añadida, asegúrese de usar un molde antiadherente para muffins O engrase el molde o los capacillos para evitar que se peguen.","Si no tiene una licuadora potente, remoje los anacardos (nueces de la India) en agua caliente durante 30 minutos antes de licuar el glaseado. Esto ayudará a que se hinchen y se ablanden, y será más fácil licuarlos hasta obtener un glaseado suave.","Escurra el tofu y séquelo con toallas de papel para eliminar el exceso de líquido y evitar que el glaseado quede demasiado líquido.","Si el glaseado se calienta mientras lo licúa (esto puede ocurrir con licuadoras potentes), páselo a un tazón y colóquelo en el congelador durante 30 minutos antes de aplicarlo con manga pastelera sobre los cupcakes.","Deje que los cupcakes se enfríen en el molde para muffins durante al menos 10 minutos antes de manipularlos. Luego páselos a una rejilla para que se enfríen por completo ANTES de glasearlos."],[]))
